// Middleware signature: (store) => (next) => (action) => next(action)

const logger = (store) => (next) => (action) => {
  // 1. Store: access state, dispatch, getState
  console.log('Current state before:', store.getState());
  console.log('Action:', action);

  // 2. Next: pass action to next middleware or reducer
  const result = next(action);

  // 3. After reducer runs
  console.log('State after:', store.getState());

  // Return result for chaining
  return result;
};

// If middleware doesn't call next(), action is STOPPED
const blocker = (store) => (next) => (action) => {
  if (action.type === 'BLOCKED_ACTION') {
    console.log('Blocking this action!');
    return; // Action never reaches reducer
  }
  return next(action);
};

// Creating a more complete logger middleware
const loggerMiddleware = (store) => {
  // Return the inner middleware
  return (next) => {
    // Return the innermost function (handles actions)
    return (action) => {
      // Add timestamp
      const timestamp = new Date().toISOString();
      const prevState = store.getState();

      console.group(`Action @ ${timestamp}`);
      console.log('Action type:', action.type);
      console.log('Payload:', action.payload);
      console.log('Previous state:', prevState);

      // Call next to let action flow through
      const returnValue = next(action);

      console.log('Next state:', store.getState());
      console.groupEnd();

      // Return value for redux-thunk compatibility
      return returnValue;
    };
  };
};

// Usage in store configuration
import { configureStore } from '@reduxjs/toolkit';
import rootReducer from './rootReducer';

const store = configureStore({
  reducer: rootReducer,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware().concat(loggerMiddleware),
});

// Middleware that handles promise actions
const asyncMiddleware = (store) => (next) => (action) => {
  // If action is a function (thunk), call it with store
  if (typeof action === 'function') {
    return action(store.dispatch, store.getState);
  }

  // If action is a promise, resolve it and dispatch result
  if (action.payload && typeof action.payload.then === 'function') {
    return action.payload
      .then((result) => {
        store.dispatch({ ...action, payload: result });
      })
      .catch((error) => {
        store.dispatch({ ...action, payload: error, error: true });
      });
  }

  // Regular action - just pass through
  return next(action);
};

// Usage: dispatch returns a promise
store.dispatch(fetchUser(123)).then(() => {
  console.log('User loaded!');
});
